#include "../core/internal.h"
#include "laststate/stream_transport.h"
#include "laststate/envelope.h"
ls_result_t ls_stream_transport_send(void *context,const uint8_t *data,size_t length){ls_stream_transport_t *stream=(ls_stream_transport_t *)context;if(!stream||!stream->write||!data||length>0xffffffffu)return LS_EINVAL;ls_envelope_info_t info;ls_result_t result=ls_envelope_validate(data,length,&info);if(result!=LS_OK)return result;uint8_t header[8]={'L','S',1,0,(uint8_t)length,(uint8_t)(length>>8),(uint8_t)(length>>16),(uint8_t)(length>>24)};result=stream->write(stream->context,header,sizeof header);if(result==LS_OK)result=stream->write(stream->context,data,length);uint32_t crc=ls_crc32(data,length);uint8_t trailer[4]={(uint8_t)crc,(uint8_t)(crc>>8),(uint8_t)(crc>>16),(uint8_t)(crc>>24)};if(result==LS_OK)result=stream->write(stream->context,trailer,sizeof trailer);if(result==LS_OK&&stream->wait_ack)result=stream->wait_ack(stream->context,info.event_id,stream->ack_timeout_ms);return result;}
size_t ls_stream_transport_max_payload(void *context){ls_stream_transport_t *stream=(ls_stream_transport_t *)context;return stream&&stream->maximum_envelope?stream->maximum_envelope:LS_MAX_EVENT_SIZE;}
